// ============================================================================
// Comprehensive Pune Office Cards Aggregator & Lookup Helper
// ============================================================================
export const allPuneOfficeCards = [
  ...puneOfficeCards,
  ...morePuneOfficeCards,
  ...finalPuneOfficeCards,
  ...featuredPuneOfficeCards,
  ...pageTwoPuneOfficeCards,
  ...pageTwoMorePuneOfficeCards,
  ...pageTwoFinalPuneOfficeCards,
  ...pageTwoFeaturedPuneOfficeCards,
  ...pageThreePuneOfficeCards,
  ...pageThreeMorePuneOfficeCards,
  ...pageThreeFinalPuneOfficeCards,
  ...pageThreeFeaturedPuneOfficeCards,
  ...(typeof pageFourPuneOfficeCards !== 'undefined' ? pageFourPuneOfficeCards : []),
  ...(typeof pageFourMorePuneOfficeCards !== 'undefined' ? pageFourMorePuneOfficeCards : []),
  ...(typeof pageFourFinalPuneOfficeCards !== 'undefined' ? pageFourFinalPuneOfficeCards : []),
  ...(typeof pageFourFeaturedPuneOfficeCards !== 'undefined' ? pageFourFeaturedPuneOfficeCards : []),
  // Include all 9 recognized similar spaces for detail page lookup
  ...similarPuneOfficeCards,
  // Include all area-specific extra cards for detail page lookup
  ...(typeof areaExtraOfficeCards !== 'undefined' ? Object.values(areaExtraOfficeCards).flat() : [])
];

const gurugramDirectorySlugs = {
  'Udyog Vihar': 'udyog-vihar',
  'Sector 44': 'sector-44',
  'Sohna Road': 'sohna-road',
  'MG Road Gurugram': 'mg-road-gurugram',
  'Golf Course Road': 'golf-course-road',
  'DLF Cyber City': 'dlf-cyber-city',
  'Unitech Cyber Park': 'unitech-cyber-park',
  'Cyber Hub': 'cyber-hub',
  'Golf Course Extension Road': 'golf-course-extension-road',
  'Cyber City': 'cyber-city',
  'Huda City Centre': 'huda-city-centre',
  'Sector 18': 'sector-18',
  'Sector 29': 'sector-29',
  'Sushant Lok': 'sushant-lok',
  'Sector 39': 'sector-39',
  'Sector 49': 'sector-49',
  'Sector 38': 'sector-38',
  'Sector 48': 'sector-48',
  'Sector 54': 'sector-54',
  'DLF Phase 4': 'dlf-phase-4',
  'Sector 67': 'sector-67',
  'NH 8': 'nh-8',
  'DLF Phase 3': 'dlf-phase-3',
  'Iffco Chowk': 'iffco-chowk',
  'Ambience Mall': 'ambience-mall'
};

const normalizeGurugramArea = (value) => String(value || '').trim().toLowerCase();

export const gurugramCoworkingSpacesBySubLocation = Object.fromEntries(
  puneNeighborhoods.map((subLocation) => [
    subLocation,
    allPuneOfficeCards
      .filter((office) => normalizeGurugramArea(office.area) === normalizeGurugramArea(subLocation))
      .map((office) => {
        const images = [...new Set(office.images || [])];
        const monthlyPrice = office.priceFormatted || `${office.price || ''} ${office.period || ''}`.trim();

        return {
          ...office,
          subLocation,
          location: office.location || office.address || '',
          address: office.address || office.location || '',
          price: monthlyPrice,
          priceFormatted: office.priceFormatted || office.price,
          mainImage: office.mainImage || images[0] || '',
          images,
          sourceUrl: `https://cofynd.com/coworking/gurugram/${gurugramDirectorySlugs[subLocation]}`
        };
      })
  ])
);

Object.assign(
  areaExtraOfficeCards,
  Object.fromEntries(
    Object.entries(gurugramCoworkingSpacesBySubLocation).map(([subLocation, offices]) => [
      subLocation,
      offices.map((office) => ({
        ...office,
        price: office.priceFormatted || office.price,
        priceFormatted: office.priceFormatted || office.price
      }))
    ])
  )
);

/**
 * Find a Pune office card by ID across all pagination pages
 * @param {string|number} id
 * @returns {object|null}
 */
export const getPuneOfficeCardById = (id) => {
  const normalizedId = String(id);
  const listedOffice = allPuneOfficeCards.find((card) => String(card.id) === normalizedId);
  if (listedOffice) return listedOffice;

  return Object.values(gurugramSimilarSpacesByArea)
    .flat()
    .find((card) => String(card.id) === normalizedId) || null;
};

